// Portfolio front end. All content comes from manifest.json (generated by build.py).

const el = (tag, cls, text) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text) e.textContent = text;
  return e;
};

// Encode each path segment so filenames with spaces, #, ? etc. still load.
const url = (path) => path.split("/").map(encodeURIComponent).join("/");

const projectUrl = (slug) => `project.html?p=${encodeURIComponent(slug)}`;

// Swipeable carousel built on native CSS scroll-snap (touch, trackpad, arrows, keys).
function Carousel(root, items, renderExtra) {
  const track = el("div", "carousel-track");
  items.forEach((item) => {
    const fig = el("figure", "slide");
    const img = el("img");
    img.src = url(item.src);
    img.alt = item.caption || "";
    img.loading = "lazy";
    img.decoding = "async";
    fig.append(img);
    const cap = el("figcaption");
    if (item.caption) cap.append(el("span", "caption", item.caption));
    if (renderExtra) renderExtra(item, cap);
    fig.append(cap);
    track.append(fig);
  });

  const prev = el("button", "carousel-btn prev", "‹");
  const next = el("button", "carousel-btn next", "›");
  prev.setAttribute("aria-label", "Previous");
  next.setAttribute("aria-label", "Next");
  const counter = el("div", "carousel-counter");
  root.append(track, prev, next, counter);

  const pad = (n) => String(n).padStart(2, "0");
  const index = () => Math.round(track.scrollLeft / track.clientWidth);
  const go = (i, smooth = true) => {
    i = Math.max(0, Math.min(items.length - 1, i));
    track.scrollTo({ left: i * track.clientWidth, behavior: smooth ? "smooth" : "instant" });
  };
  const update = () => {
    const i = index();
    counter.textContent = `${pad(i + 1)} / ${pad(items.length)}`;
    prev.disabled = i === 0;
    next.disabled = i === items.length - 1;
  };

  prev.onclick = () => go(index() - 1);
  next.onclick = () => go(index() + 1);
  track.addEventListener("scroll", update, { passive: true });
  update();

  return { go, prev: () => go(index() - 1), next: () => go(index() + 1) };
}

function fillSite(site) {
  if (site.name) document.title = document.body.dataset.page === "home" ? site.name : `${document.title} — ${site.name}`;
  document.querySelectorAll("[data-site-name]").forEach((e) => (e.textContent = site.name || ""));
  document.querySelectorAll("[data-site-tagline]").forEach((e) => (e.textContent = site.tagline || ""));
  document.querySelectorAll("[data-site-realname]").forEach((e) => (e.textContent = site.realName || ""));
  document.getElementById("year").textContent = new Date().getFullYear();
}

// Hide the News menu link on every page while there are no articles.
function toggleNewsLinks(news) {
  document.querySelectorAll('nav a[href$="#news"]').forEach((a) => (a.hidden = !news.length));
}

function renderHome(m) {
  const overviewRoot = document.getElementById("overview");
  const titles = Object.fromEntries(m.projects.map((p) => [p.slug, p.title]));
  const carousel = Carousel(overviewRoot, m.overview, (item, cap) => {
    const a = el("a", "slide-project", titles[item.project]);
    a.href = projectUrl(item.project);
    cap.append(a);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft") carousel.prev();
    if (e.key === "ArrowRight") carousel.next();
  });

  const grid = document.getElementById("project-grid");
  m.projects.forEach((p) => {
    const a = el("a", "project-card");
    a.href = projectUrl(p.slug);
    const img = el("img");
    img.src = url(p.images[0].src);
    img.alt = "";
    img.loading = "lazy";
    const meta = el("div", "project-meta");
    meta.append(el("span", "project-name", p.title), el("span", "project-count", `${p.images.length} works`));
    a.append(img, meta);
    grid.append(a);
  });

  const newsList = document.getElementById("news-list");
  m.news.forEach((n) => {
    const card = el(n.link ? "a" : "div", "news-card");
    if (n.link) {
      card.href = n.link;
      card.target = "_blank";
      card.rel = "noopener";
    }
    if (n.image) {
      const img = el("img");
      img.src = url(n.image);
      img.alt = n.title;
      img.loading = "lazy";
      card.append(img);
    }
    card.append(
      el("div", "news-meta", [n.date, n.source].filter(Boolean).join(" · ")),
      el("div", "news-title", n.title),
      el("p", "news-text", n.text)
    );
    if (!n.link) card.querySelector(".news-title").classList.add("no-link");
    const li = el("li");
    li.append(card);
    newsList.append(li);
  });
  document.getElementById("news").hidden = !m.news.length;

  const portrait = document.getElementById("portrait");
  if (m.about.portrait) {
    portrait.src = url(m.about.portrait);
    portrait.alt = m.site.name || "Portrait";
    portrait.hidden = false;
  }
  const bio = document.getElementById("bio");
  m.about.bio.split(/\n\s*\n/).filter(Boolean).forEach((para) => bio.append(el("p", null, para)));

  const contact = document.getElementById("contact");
  const links = (m.site.links || []).slice();
  if (m.site.email) links.unshift({ label: m.site.email, url: `mailto:${m.site.email}` });
  links.forEach((l) => {
    const a = el("a", null, l.label);
    a.href = l.url;
    if (!l.url.startsWith("mailto:")) {
      a.target = "_blank";
      a.rel = "noopener";
    }
    const li = el("li");
    li.append(a);
    contact.append(li);
  });
}

function renderProject(m) {
  const slug = new URLSearchParams(location.search).get("p");
  const p = m.projects.find((x) => x.slug === slug);
  const titleEl = document.getElementById("project-title");
  if (!p) {
    titleEl.textContent = "Project not found";
    return;
  }
  document.title = p.title + (m.site.name ? ` — ${m.site.name}` : "");
  titleEl.textContent = p.title;
  const desc = document.getElementById("project-description");
  p.description.split(/\n\s*\n/).filter(Boolean).forEach((para) => desc.append(el("p", null, para)));

  const lightbox = document.getElementById("lightbox");
  const carousel = Carousel(document.getElementById("lightbox-carousel"), p.images);
  const open = (i) => {
    lightbox.hidden = false;
    document.body.classList.add("no-scroll");
    carousel.go(i, false);
  };
  const close = () => {
    lightbox.hidden = true;
    document.body.classList.remove("no-scroll");
  };
  lightbox.querySelector(".lightbox-close").onclick = close;
  lightbox.addEventListener("click", (e) => {
    if (e.target.classList.contains("slide")) close();
  });
  document.addEventListener("keydown", (e) => {
    if (lightbox.hidden) return;
    if (e.key === "Escape") close();
    if (e.key === "ArrowLeft") carousel.prev();
    if (e.key === "ArrowRight") carousel.next();
  });

  const gallery = document.getElementById("gallery");
  p.images.forEach((item, i) => {
    const fig = el("figure", "gallery-item");
    const img = el("img");
    img.src = url(item.src);
    img.alt = item.caption || "";
    img.loading = "lazy";
    img.onclick = () => open(i);
    fig.append(img);
    if (item.caption) fig.append(el("figcaption", null, item.caption));
    gallery.append(fig);
  });
}

function renderCV(m) {
  const root = document.getElementById("cv");
  m.cv.forEach((section) => {
    const s = el("section", "cv-section");
    s.append(el("h2", "section-title", section.title));
    const list = el("dl", "cv-list");
    section.entries.forEach((e) => list.append(el("dt", null, e.year), el("dd", null, e.text)));
    s.append(list);
    root.append(s);
  });
}

function renderEducation(m) {
  const root = document.getElementById("education");
  m.education.forEach((p) => {
    const item = el("article", "edu-item");
    const body = el("div");
    body.append(el("h2", "edu-title", p.title));
    p.text.split(/\n\s*\n/).filter(Boolean).forEach((para) => body.append(el("p", null, para)));
    item.append(el("div", "edu-year", p.year), body);
    root.append(item);
  });
}

fetch("manifest.json", { cache: "no-cache" })
  .then((r) => r.json())
  .then((m) => {
    fillSite(m.site);
    toggleNewsLinks(m.news);
    ({ home: renderHome, project: renderProject, cv: renderCV, education: renderEducation })[document.body.dataset.page](m);
    // Content renders after load, so re-apply a #section jump (e.g. ./#about from a project page).
    if (location.hash) document.querySelector(location.hash)?.scrollIntoView();
  })
  .catch((err) => {
    console.error(err);
    document.querySelector("main").prepend(el("p", "error", "Could not load manifest.json — run `python3 build.py`."));
  });
